package fr.cercle.sixtuiles;import java.util.*;public class EngineTest{static int n;static void check(boolean b){n++;if(!b)throw new AssertionError("test "+n);}public static void main(String[] args){check(Arrays.equals(Engine.evaluate(new int[]{1,2,3,4},new int[]{1,3,2,5}),new int[]{1,2}));check(Arrays.equals(Engine.evaluate(new int[]{1,2,3,4},new int[]{4,3,2,1}),new int[]{0,4}));for(int seed=0;seed<100;seed++){Engine c=new Engine(0,seed);c.guess=new int[]{1,1,1,1};check(!c.submit()&&c.turn==0);c.guess=c.secret.clone();check(c.submit()&&c.over&&c.won&&c.score==600);check(!c.submit());Engine t=new Engine(1,seed);for(int i=0;i<6;i++){int x=t.route[i][0],y=t.route[i][1];int need=(i==0?8:Engine.dir(t.route[i-1][0]-x,t.route[i-1][1]-y))|(i==5?2:Engine.dir(t.route[i+1][0]-x,t.route[i+1][1]-y));t.selected=t.offers[0]==need?0:1;t.px=x;t.py=y;check(t.placeTile());}check(t.over&&t.won&&t.score>=100);check(!t.placeTile());Engine b=new Engine(2,seed);for(int i=0;i<8;i++){boolean placed=false;outer:for(int o=0;o<3;o++)for(int r=0;r<4;r++)for(int y=0;y<4;y++)for(int x=0;x<4;x++)if(b.fits(b.offers[o]/3,r,x,y)){b.selected=o;b.rotation=r;b.px=x;b.py=y;check(b.placeObject());placed=true;break outer;}if(!placed)b.skip();}check(b.over&&b.turn==8);for(int id=0;id<Engine.SHAPES.length;id++)for(int r=0;r<4;r++){Set<String> cells=new HashSet<>();for(int[] p:Engine.shape(id,r)){check(p[0]>=0&&p[1]>=0);cells.add(p[0]+","+p[1]);}check(cells.size()==Engine.SHAPES[id].length);}}Engine b=new Engine(2,1);b.offers[0]=0;b.selected=0;for(int x=0;x<3;x++){b.offers[0]=0;b.selected=0;b.px=x;b.py=0;check(b.placeObject());}check(b.score==64);check(!b.fits(0,0,0,0));System.out.println(n+" engine assertions PASS");}}